(()=>{
const esc=L.e,m=L.money;
const niceDate=d=>d?new Date(d+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short'}):'Not set yet';
const sum=(arr,key)=>arr.reduce((a,x)=>a+Number(x[key]||0),0);
L.balanceNumber=n=>{const p=L.moneyParts(n);return `${p.sign}<span class="currency">${p.currency}</span><span class="whole">${p.whole}</span><span class="cents">.${p.fraction}</span>`;};
L.homeMoneyStory=()=>`<button type="button" class="home-money-story" onclick="L.go('story')"><span class="home-story-icon" aria-hidden="true">${L.icon('receipt',21)}</span><span class="home-story-copy"><strong>Your money story</strong><small>See where your money went.</small></span>${L.icon('arrowRight',19)}</button>`;
L.views.home=()=>{
 const st=L.state,b=L.balances(),name=esc(st.profile.name.split(' ')[0]),funded=b.available>0;
 return `<div class="home-greeting"><a class="wordmark" onclick="L.go('home')"><img class="actual-wordmark lumo-wordmark-asset" src="/brand/Lumo-Wordmark-Black.svg" alt="Lumo"></a><div class="inline"><button class="icon-btn" aria-label="Updates" onclick="L.go('notifications')">${L.icon('bell',21)}</button><button class="avatar" style="border:0" onclick="L.go('profile')">${name[0]}</button></div></div><p class="small muted">Hey, ${name}.</p><div class="hero"><button class="text-btn balance-label" style="padding:0" onclick="L.go('balances')">Available balance ${L.icon('chevron',13)}</button><div class="balance-main"><span class="balance-accent">${L.balanceNumber(b.available)}</span></div></div>${L.illustration?L.illustration(funded?'home':'funding'):''}<div class="quick-actions">${[['plus','Add money',"L.openFunding('home')"],['arrowUp','Send',"L.startSend('lumo')"],['scan','Campus Pay',"L.go('campusPay')"],['arrowDown','Request','L.newRequest()']].map(([i,t,action])=>`<button onclick="${action}"><span>${L.icon(i)}</span>${t}</button>`).join('')}</div>${funded?`<button class="home-compact-plan" onclick="L.go('plan')"><span><span class="eyebrow">AFTER YOUR SAVED PLAN</span><strong>${m(b.room)}</strong><small>${b.gap?m(b.gap)+' still uncovered':'Room after essentials and goal allocations'}</small></span>${L.icon('arrowRight',20)}</button>`:L.btn('Add my first money',"L.openFunding('home')")}${L.homeMoneyStory()}<div class="section-head"><h2>Latest</h2><button class="text-btn" onclick="L.go('activity')">See all</button></div>${st.txs.length?st.txs.slice(0,2).map(t=>L.row(t.name,t.status==='pending'?'In progress':new Date(t.date).toLocaleDateString('en-GB',{day:'numeric',month:'short'}),t.type==='in'?'arrowDown':'arrowUp',`L.go('txDetail',{id:'${t.id}'})`,`${t.type==='in'?'+':'−'}${m(t.amount)}`)).join(''):'<p class="small muted" style="padding:15px 0">Your first money moment starts here.</p>'}${L.row('Ask your money','Talk it through','chat',"L.go('chat')")}`;
};
L.views.balances=()=>{const b=L.balances();return L.header('Your balance','A clear view of what’s available.')+`<div class="receipt">${[['Current balance',b.current],['Pending payments',-b.held],['Available balance',b.available]].map(([t,n])=>`<div class="summary-line"><span>${t}</span><strong>${m(n)}</strong></div>`).join('')}</div><div class="section-head"><h2>After your plan</h2></div><div class="stack"><div class="summary-line"><span>Upcoming essentials</span><strong>−${m(b.essentials)}</strong></div><div class="summary-line"><span>Money set aside for goals</span><strong>−${m(b.allocated)}</strong></div><div class="soft split"><strong>Left after your plan</strong><strong>${m(b.room)}</strong></div>${b.gap?`<p class="warning">Your plan needs ${m(b.gap)} more.</p>`:''}<details class="screen-explainer"><summary>Balance and plan, explained</summary><p class="small muted">Pending outgoing payments are reserved. Your expected allowance isn’t money received. Goals and essentials are plans for available money, so they do not lock it away.</p></details>${L.btn('Open my plan',"L.openTab('plan')",'secondary')}</div>`;};
L.views.plan=()=>{const s=L.state,b=L.balances();return L.header('Make room for your life.','A little structure. Plenty of living.')+`<div class="hero"><p class="small muted">Estimated room to spend</p><div class="balance-main" style="font-size:45px">${L.balanceNumber(b.room)}</div><p class="balance-context">After ${m(b.essentials)} essentials + ${m(b.allocated)} goal allocations.</p></div>${b.gap?`<div class="warning">Your plan needs ${m(b.gap)} more to be fully covered. ${L.btn('Find some room',"L.go('makeRoom')",'text-btn')}</div>`:''}${!s.allowance.amount&&!s.essentials.length&&!s.goals.length?L.btn(s.planDraft?'Continue my plan draft':'Set up my first plan',"L.go(L.state.planDraft?.step||'planSetup')",'secondary'):''}<div class="list">${L.row('My allowance',s.allowance.amount?m(s.allowance.amount)+' expected · '+niceDate(s.allowance.date):'What’s coming, and when','arrowDown',"L.go('allowance')")}${L.row('Upcoming essentials',s.essentials.length?s.essentials.length+' things to take care of':'Food, transport, data. The usual.','plan',"L.go('essentials')")}${L.row('Something to aim for',s.goals.length?s.goals.map(g=>g.name).join(', '):'Give a future plan a name','target',"L.go('goals')")}</div><div class="section-head"><h2>Your money story</h2></div><div class="story-preview"><span class="eyebrow accent">LESS “WHERE DID IT GO?”</span><h2 style="margin-top:12px">See the shape<br>of your spending.</h2><p>A clear picture of what you’ve actually spent.</p><button class="text-btn" onclick="L.go('story')">Read my story ↗</button></div>${L.row('Small steps, real progress','See your completed milestones','gift',"L.go('missions')")}<p class="small muted">Planning is optional. You can always use Lumo to pay and receive money.</p>`;};
L.views.allowance=()=>{const a=L.state.allowance;return L.header('The next top-up.','What are you expecting? It only becomes account money when it arrives.')+L.field('Expected amount (GH₵)','allowanceAmount','For example, 1,200','number',a.amount||'')+L.field('Expected date (optional)','allowanceDate','','date',a.date)+L.field('Where it usually comes from','allowanceSource','Family, work, a side hustle','text',a.source)+`<div id="error"></div><div class="actions">${L.btn('Save allowance plan','L.saveAllowance()')}${L.btn('I’m not sure yet','L.saveAllowance(true)','secondary')}</div><p class="small muted" style="margin-top:20px">An estimate is fine. You can change it whenever life changes.</p>`;};
L.saveAllowance=unknown=>{const amount=unknown?0:L.moneyInput(L.value('allowanceAmount'));const date=unknown?'':L.value('allowanceDate');if(!unknown&&(amount===null))return L.error('Enter a valid expected amount, or choose “I’m not sure yet”.');L.state.allowance={amount,date,source:L.value('allowanceSource')||'Not set'};L.save();L.finishForm('plan');L.toast('Allowance plan saved. Your account balance hasn’t changed.');};
L.views.essentials=()=>{const page=L.compactPage?L.compactPage(L.state.essentials,3):{items:L.state.essentials,pages:1};return L.header('Your budget items','The costs this money needs to cover.')+page.items.map(x=>{const held=L.state.txs.filter(t=>t.essentialId===x.id&&t.status==='pending').reduce((a,t)=>a+t.amount,0);return L.row(x.name,held?'Payment in progress':Math.max(0,x.amount-(x.paid||0))===0?'Covered':x.date?'Due '+niceDate(x.date):'No due date','plan',`L.go('essentialEdit',{id:'${x.id}'})`,m(Math.max(0,x.amount-(x.paid||0)-held)));}).join('')+(!L.state.essentials.length?`<div class="empty"><h2>Make space for the basics.</h2><p class="small muted">Start with food, transport or data.</p></div>`:'')+(L.listPager?L.listPager(page):'')+`<div class="actions">${L.btn('Add a budget item',"L.go('essentialEdit')")}</div>`;};
L.views.essentialEdit=()=>{
 L.reconcileEssentialCoverage();
 const x=L.state.essentials.find(item=>item.id===L.params.id)||{},p=L.pauseEngine.planPosition({amount:0,fee:0}),remaining=p.essentials.find(item=>item.id===x.id)?.before||0;
 const pending=L.state.txs.filter(tx=>tx.type==='out'&&tx.status==='pending'&&tx.essentialId===x.id).reduce((total,tx)=>total+Number(tx.amount),0);
 const fact=(label,value)=>`<div class="summary-line"><dt>${label}</dt><dd>${m(value)}</dd></div>`;
 const coverage=x.id?`<dl class="essential-coverage" aria-label="Coverage for this cost">${fact('Already covered',x.paid||0)}${pending?fact('Payment in progress',pending):''}${fact('Still to cover',remaining)}</dl>`:'';
 return L.header(x.id?'Edit budget item':'Add a budget item')+L.field('Give it a name','essName','Transport to lectures','text',x.name)+L.field('Budget amount (GH₵)','essAmount','100','number',x.amount).replace('<input ','<input aria-describedby="essential-total-help" ')+`<p id="essential-total-help" class="small muted">Total for the whole period, including what’s covered. Not per day.</p>`+coverage+L.field('Due date (optional)','essDate','','date',x.date)+`<div id="error"></div><div class="actions">${L.btn('Save budget item','L.saveEssential()')}${x.id?L.btn('Mark paid outside Lumo','L.markExternalEssential()','secondary')+L.btn('Remove from budget','L.removeEssential()','text-btn'):''}</div><p class="small muted" style="margin-top:18px">Saving a budget item doesn’t pay anyone or move money.</p>`;
};
L.saveEssential=()=>{const name=L.value('essName'),amount=L.moneyInput(L.value('essAmount'),.01);if(!name||amount===null)return L.error('Add a name and a positive amount.');const x=L.state.essentials.find(x=>x.id===L.params.id);if(x){if(L.state.txs.some(t=>t.essentialId===x.id&&t.status==='pending'))return L.error('This budget item has a payment in progress. Check its status before editing.');Object.assign(x,{name,amount,date:L.value('essDate'),paid:Math.min(amount,x.paid||0)});}else L.state.essentials.push({id:L.id('ess'),name,amount,date:L.value('essDate'),paid:0});L.save();L.finishForm('essentials');L.toast('Budget item saved.');};
L.markExternalEssential=()=>{const x=L.state.essentials.find(x=>x.id===L.params.id);if(!x)return;if(L.state.txs.some(t=>t.essentialId===x.id&&t.status==='pending'))return L.error('Check the payment in progress first.');if(!confirm('Mark this cost as fully covered outside Lumo? This updates your budget, not your account balance.'))return;L.markEssentialCoveredOutside(x.id);L.save();L.go('essentials');};
L.removeEssential=()=>{const id=L.params.id;if(L.state.txs.some(t=>t.essentialId===id&&t.status==='pending'))return L.error('Wait for the linked payment result before removing this cost.');if(confirm('Remove this cost from your budget?')){L.state.essentials=L.state.essentials.filter(x=>x.id!==id);L.save();L.go('essentials');}};
L.views.goals=()=>{
 const page=L.compactPage?L.compactPage(L.state.goals,3):{items:L.state.goals,pages:1},saved=L.state.goals.find(g=>g.id===L.params.savedGoalId);
 const notice=saved?`<div class="notice goal-saved" role="status"><strong>${esc(saved.name)} ${L.params.goalSavedAction==='updated'?'updated':'added'}.</strong><p class="small">Your goal is saved. Set aside money whenever you’re ready.</p></div>`:'';
 return L.header('Your goals','Something to look forward to.')+notice+page.items.map(g=>`<button type="button" class="goal-summary card" onclick="L.go('goal',{id:'${g.id}'})"><div class="split"><h3>${esc(g.name)}</h3>${L.icon('chevron',18)}</div><p class="small muted">${m(g.allocated)} of ${m(g.target)}</p><div class="progress" role="progressbar" aria-label="${esc(g.name)} money set aside" aria-valuemin="0" aria-valuemax="${g.target}" aria-valuenow="${Math.min(g.allocated,g.target)}"><div class="progress-bar" style="width:${Math.min(100,g.allocated/g.target*100)}%"></div></div></button>`).join('')+(!L.state.goals.length?`<div class="empty"><h2>What’s your next big thing?</h2><p class="small muted">A laptop. A trip. A little breathing room.</p></div>`:'')+(L.listPager?L.listPager(page):'')+`<div class="actions">${L.btn(L.state.goals.length?'Add another goal':'Add a goal',"L.go('goalEdit')")}${L.btn('Close','L.taskSheet?.active?L.closeTask():L.openTab(\'plan\')','secondary')}</div>`;
};
L.views.goalEdit=()=>{
 const g=L.state.goals.find(g=>g.id===L.params.id)||{};
 return L.header(g.id?'Edit your goal':'Add a goal')+L.field('Goal name','goalName','My next laptop','text',g.name)+L.field('Target amount (GH₵)','goalTarget','3500','number',g.target)+`<div id="error"></div><div class="actions">${L.btn(g.id?'Save changes':'Add goal','L.saveGoal()')}${L.btn('Cancel',"L.go('goals')",'text-btn')}</div><p class="small muted" style="margin-top:20px">A target doesn’t reserve money. Set aside an amount after adding your goal.</p>`;
};
L.saveGoal=()=>{
 if(L.route!=='goalEdit')return;
 const name=L.value('goalName'),target=L.moneyInput(L.value('goalTarget'),.01);
 if(!name||name.length>80||target===null)return L.error('Give your goal a name (up to 80 characters) and a positive target.');
 let g=L.state.goals.find(g=>g.id===L.params.id);const updating=!!g;
 if(g){if(target<Number(g.allocated||0))return L.error('Set aside less first, or keep the target at least as high as the money set aside.','goalTarget');Object.assign(g,{name,target});}
 else {g={id:L.id('goal'),name,target,allocated:0};L.state.goals.push(g);}
 L.syncPlanDraftGoal?.(g.id);L.save();L.finishForm('goals',{savedGoalId:g.id,goalSavedAction:updating?'updated':'added'});L.toast(updating?'Goal updated.':'Goal added.');
};
L.views.goal=()=>{const g=L.state.goals.find(g=>g.id===L.params.id);if(!g)return L.views.goals();return L.header(g.name,'A plan for some of your money. Always yours to change.')+`<div class="hero"><p class="small muted">Set aside in your plan</p><div class="balance-main" style="font-size:44px">${L.balanceNumber(g.allocated)}</div><p class="small muted" style="margin-top:13px">of ${m(g.target)} target</p><div class="progress" style="margin:22px 0"><div class="progress-bar" style="width:${Math.min(100,g.allocated/g.target*100)}%"></div></div></div><div class="actions">${L.btn('Set aside money',`L.go('allocate',{id:'${g.id}'})`)}${L.btn('Set aside less',`L.go('releaseGoal',{id:'${g.id}'})`,'secondary')}${L.btn('Edit goal',`L.go('goalEdit',{id:'${g.id}'})`,'text-btn')}${L.btn(g.allocated>=g.target?'Complete goal':'Archive goal',`L.archiveGoal('${g.id}')`,'text-btn')}</div><details class="screen-explainer"><summary>How setting money aside works</summary><p class="small muted">Setting money aside changes your plan. Your money stays available in your account.</p></details>`;};
L.views.allocate=()=>{const g=L.state.goals.find(g=>g.id===L.params.id);if(!g)return L.views.goals();return L.header('A little closer.',esc(g.name))+`<div class="notice">You have ${m(L.balances().room)} left after your plan.</div>`+L.field('Amount to set aside (GH₵)','allocation','50','number')+`<div id="error"></div>${L.btn('Review amount set aside','L.reviewAllocation()')}`;};
L.reviewAllocation=()=>{const amount=L.moneyInput(L.value('allocation'),.01);if(amount===null||amount>L.balances().room)return L.error('Choose an amount within what’s left after your plan, using up to 2 decimal places.','allocation');L.clearFormDraft();L.skipFormCapture=true;try{L.go('allocationReview',{id:L.params.id,amount,operationId:L.id('plan-op')});}finally{L.skipFormCapture=false;}};
L.views.allocationReview=()=>{const g=L.state.goals.find(g=>g.id===L.params.id);if(!g)return L.views.goals();const a=L.params.amount;L.params.operationId=L.params.operationId||L.id('plan-op');return L.header('Review amount set aside','Check the change before saving.')+`<div class="receipt"><h2>${esc(g.name)}</h2><div class="summary-line"><span>Set aside now</span><strong>${m(g.allocated)}</strong></div><div class="summary-line"><span>Setting aside</span><strong>${m(a)}</strong></div><div class="summary-line"><span>Set aside after this change</span><strong>${m(g.allocated+a)}</strong></div><div class="summary-line"><span>Left after your plan</span><strong>${m(Math.max(0,L.balances().room-a))}</strong></div></div><div class="notice">Your account balance stays the same. This is a planning choice.</div><div id="error"></div>${L.btn('Save amount set aside','L.confirmAllocation()')}`;};
L.confirmAllocation=()=>{const g=L.state.goals.find(g=>g.id===L.params.id),a=L.moneyInput(L.params.amount,.01),op=L.params.operationId;L.state.planOperations=L.state.planOperations||[];if(op&&L.state.planOperations.includes(op)){L.go('goal',{id:L.params.id});L.toast('This amount is already set aside.');return;}if(!g||!op||a===null||a>L.balances().room)return L.error('Your available room changed. Review the amount again.');g.allocated=Math.round((g.allocated+a)*100)/100;L.state.planOperations.push(op);L.syncPlanDraftGoal?.(g.id);L.save();L.go('goal',{id:g.id});L.toast('Money set aside in your plan.');};
L.views.releaseGoal=()=>{const g=L.state.goals.find(g=>g.id===L.params.id);if(!g)return L.views.goals();return L.header('Set aside less.',`Reduce the money set aside for ${esc(g.name)}. Your available balance stays the same.`)+`<div class="notice">Set aside now: ${m(g.allocated)}</div>`+L.field('Reduce by (GH₵)','release','50','number')+`<div id="error"></div>${L.btn('Review change','L.reviewRelease()')}`;};
L.reviewRelease=()=>{const g=L.state.goals.find(g=>g.id===L.params.id),a=L.moneyInput(L.value('release'),.01);if(!g||a===null||a>g.allocated)return L.error('Choose an amount within the money set aside for this goal, using up to 2 decimal places.','release');L.clearFormDraft();L.skipFormCapture=true;try{L.go('releaseReview',{id:g.id,amount:a,returnTo:L.params.returnTo||'goal',operationId:L.id('plan-op')});}finally{L.skipFormCapture=false;}};
L.views.releaseReview=()=>{const g=L.state.goals.find(g=>g.id===L.params.id);if(!g)return L.views.goals();L.params.operationId=L.params.operationId||L.id('plan-op');return L.header('Review change','Check the change before saving.')+`<div class="receipt"><h3>${esc(g.name)}</h3><div class="summary-line"><span>Reduce amount set aside</span><strong>${m(L.params.amount)}</strong></div><div class="summary-line"><span>Still set aside</span><strong>${m(g.allocated-L.params.amount)}</strong></div><div class="summary-line"><span>Available balance</span><strong>${m(L.balances().available)}</strong></div></div><div class="notice">This doesn’t add money. It changes how you plan to use money already available.</div>${L.btn('Save change','L.confirmRelease()')}`;};
L.confirmRelease=()=>{const g=L.state.goals.find(g=>g.id===L.params.id),a=L.moneyInput(L.params.amount,.01),op=L.params.operationId;L.state.planOperations=L.state.planOperations||[];if(op&&L.state.planOperations.includes(op)){L.go('goal',{id:L.params.id});L.toast('This change is already saved.');return;}if(!g||!op||a===null||a>g.allocated)return L.error('The money set aside changed. Review the amount again.');g.allocated=Math.round((g.allocated-a)*100)/100;L.state.planOperations.push(op);L.syncPlanDraftGoal?.(g.id);L.save();if(L.params.returnTo==='paymentReview'&&L.state.paymentDraft&&!L.state.paymentDraft.submittedTxId){L.go('paymentReview');L.toast('Plan updated. Review your payment again.');}else{L.go('goal',{id:g.id});L.toast('Amount set aside updated.');}};
L.archiveGoal=id=>{const g=L.state.goals.find(g=>g.id===id);if(!g)return;if(confirm(g.allocated?`Archive this goal and stop setting aside ${m(g.allocated)} for it? Your account balance stays the same.`:'Archive this goal?')){L.state.goals=L.state.goals.filter(g=>g.id!==id);L.syncPlanDraftGoal?.(id);L.save();L.go('goals');}};
L.views.makeRoom=()=>L.header('A change of plan is still a plan.','Choose what to adjust. Nothing here sends money.')+`<div class="notice">Available balance: ${m(L.balances().available)}. Setting aside less for a goal changes what’s left after your plan. Your balance stays the same.</div>`+L.state.goals.filter(g=>g.allocated>0).map(g=>L.row(g.name,m(g.allocated)+' set aside','target',`L.go('releaseGoal',{id:'${g.id}',returnTo:L.params.returnTo||'plan'})`)).join('')+L.row('Review upcoming essentials','Edit a cost if your plans changed','plan',"L.go('essentials')")+L.row('Add actual money','Fund the account before spending more','plus',"L.openFunding(L.params.returnTo==='paymentReview'?'paymentReview':'plan')")+L.btn(L.params.returnTo==='paymentReview'?'Back to payment review':'Back to my plan',L.params.returnTo==='paymentReview'?"L.go('paymentReview')":"L.go('plan')",'secondary');
L.views.story=()=>{const days=[7,30,90].includes(Number(L.params.days))?Number(L.params.days):30,cutoff=Date.now()-days*86400000;const txs=L.state.txs.filter(t=>t.type==='out'&&t.status==='success'&&new Date(t.date).getTime()>=cutoff),groups={};txs.forEach(t=>groups[t.category||'Other']=(groups[t.category||'Other']||0)+Number(t.amount)+Number(t.fee||0));const total=txs.reduce((n,t)=>n+Number(t.amount)+Number(t.fee||0),0);return L.header('Your money story','See where it went, including fees.')+`<div class="chips" aria-label="Spending period">${[7,30,90].map(d=>L.btn(d+' days',`L.go('story',{days:${d}})`,'chip '+(days===d?'selected':''))).join('')}</div><p class="small muted">Spent in ${days} days</p><div class="balance-main">${L.balanceNumber(total)}</div>${total?`<div class="category-bar" aria-hidden="true">${Object.values(groups).map(v=>`<span style="width:${v/total*100}%"></span>`).join('')}</div><details class="spending-breakdown"><summary>Spending by category</summary>${Object.entries(groups).sort((a,b)=>b[1]-a[1]).map(([cat,v])=>`<div class="summary-line"><span>${esc(cat)}</span><strong>${m(v)} · ${Math.round(v/total*100)}%</strong></div>`).join('')}</details><div class="list">${txs.slice(0,2).map(t=>L.row(t.name,t.category,'receipt',`L.go('storyTx',{id:'${t.id}',days:${days}})`,m(Number(t.amount)+Number(t.fee||0)))).join('')}</div>`:`<div class="empty"><h2>A fresh page.</h2><p class="small muted">Completed payments in this period will appear here.</p></div>`}<div class="actions">${total?L.btn('View all spending',`L.go('activity',{scope:'spending',filter:'out',days:${days}})`,'secondary'):L.btn('Make a payment',"L.openTab('pay')",'secondary')}${L.btn('Talk it through',"L.go('chat',{question:'Where did my money go?'})",'text-btn')}</div>`;};
L.views.storyTx=()=>{const t=L.state.txs.find(t=>t.id===L.params.id);if(!t)return L.views.story();const categories=[...new Set([t.category||'Other','Food','Transport','Study','Data','Phone','Shopping','Bills','Transfers','Other'])];return L.header('Payment category',esc(t.name))+`<div class="metric">${m(Number(t.amount)+Number(t.fee||0))}</div><label class="field"><span>Spending category</span><select id="category">${categories.map(c=>`<option ${t.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label>${L.btn('Save category',`L.setCategory('${t.id}')`)}<div class="actions">${L.btn('Open receipt',`L.go('txDetail',{id:'${t.id}'})`,'text-btn')}</div>`;};
L.setCategory=id=>{const t=L.state.txs.find(t=>t.id===id);if(t)t.category=L.value('category');L.save();L.go('story',{days:L.params.days||30});};
const suggestions=['Can I afford the weekend?','Where did my money go?','Will I run out before my allowance?','Help me make some room'];
L.chatAnswer=q=>{const b=L.balances(),s=L.state,spend=s.txs.filter(t=>t.type==='out'&&t.status==='success');const query=q.toLowerCase();if(/where|spent|spending|food/.test(query)){const total=spend.reduce((v,t)=>v+Number(t.amount)+Number(t.fee||0),0);return {text:spend.length?`You’ve spent ${m(total)} in completed payments, including fees. ${spend.slice(0,2).map(t=>t.name+' ('+m(Number(t.amount)+Number(t.fee||0))+')').join(' and ')} are part of that picture. Let’s look at the categories.`:'You don’t have confirmed spending yet. Once you pay for something, we can follow the money together.',action:'See my money story',route:'story'};}if(/room|goal|recover|tight|short/.test(query))return {text:`You have ${m(b.available)} available. Your plan covers ${m(b.essentials)} in unpaid essentials and ${m(b.allocated)} in goal allocations. ${b.gap?'That leaves a '+m(b.gap)+' gap.':'That leaves '+m(b.room)+' in estimated room.'} You could change a goal allocation or revisit a cost. Neither choice adds money to your account.`,action:'Look at my options',route:'makeRoom'};if(/weekend|afford|run out|allowance|balance|how much|spend/.test(query))return {text:!s.essentials.length&&!s.allowance.date?`You have ${m(b.available)} available, but I don’t know your upcoming costs or next allowance date yet. I can’t tell you whether that will last. Add what you know and we’ll work it out.`:`You have ${m(b.available)} available today. After your unpaid essentials and goal allocations, your estimated room is ${m(b.room)}.${b.gap?' Your plan also has a '+m(b.gap)+' coverage gap.':''}${s.allowance.date?' Your next allowance is expected on '+niceDate(s.allowance.date)+', but it hasn’t arrived yet.':''} ${b.room?'For the weekend, choose an amount within that room, leaving a little for surprises.':'A smaller spend or a change to your plan could help.'}`,action:'See the plan behind this',route:'plan'};if(/send|pay|transfer/.test(query))return {text:'I can help you get to the right place. Choose who you want to pay, check the amount and confirm it yourself. This conversation never sends money.',action:'Open payments',route:'pay'};return {text:'In this preview, I can help with your balance, spending, upcoming essentials and goal allocations. Try “Can I afford the weekend?” or “Where did my money go?” My answers use only the sample information in this account.',action:'See my plan',route:'plan'};};
L.views.chat=()=>{if(L.params.question&&!L.params.used){L.params.used=true;L.state.chats=L.state.chats||[];const q=L.params.question;L.state.chats.push({q,...L.chatAnswer(q)});L.save();}const chats=L.state.chats||[];return L.header('Talk it through.','Your money. Your questions. A little clarity.')+`<div class="chat-bubble">Hey ${esc(L.state.profile.name.split(' ')[0])}. What’s on your mind?</div>${chats.slice(-6).map(c=>`<div class="chat-bubble user">${esc(c.q)}</div><div class="chat-bubble">${esc(c.text)}${c.action?`<div style="margin-top:13px">${L.btn(c.action,`L.go('${c.route}')`,'text-btn')}</div>`:''}</div>`).join('')}<div class="chips">${suggestions.slice(0,chats.length?2:4).map((q,i)=>L.btn(esc(q),`L.askSuggestion(${i})`,'chip')).join('')}</div><form class="chat-entry" onsubmit="event.preventDefault();L.askChat()"><input id="chatText" aria-label="Ask your money" placeholder="Ask your money…" maxlength="500"><button type="submit" aria-label="Send question">${L.icon('arrowUp')}</button></form><p class="tiny muted" style="margin-top:11px">Preview answers use this account’s saved information.</p>`;};
L.askChat=()=>{const q=L.value('chatText');if(!q)return;L.state.chats=L.state.chats||[];L.state.chats.push({q,...L.chatAnswer(q)});L.clearFormDraft();L.save();L.params={};L.render();document.getElementById('chatText')?.focus?.({preventScroll:true});};L.askSuggestion=i=>L.go('chat',{question:suggestions[i]});
L.views.missions=()=>{const s=L.state,items=[['You’re in','Account set up',s.onboarded,'profile'],['A little in the tank','Add your first money',s.txs.some(t=>t.type==='in'&&t.status==='success'),'addMoney'],['Know what comes next','Add an everyday budget cost',(s.essentials||[]).some(cost=>cost&&!cost.archived&&!cost.deleted&&Number.isFinite(Number(cost.amount))&&Number(cost.amount)>0),'plan'],['Something to aim for','Create a Money Box',s.goals.length>0,'goals'],['Your first money moment','Make a payment',s.txs.some(t=>t.type==='out'&&t.status==='success'),'pay']];return L.header('Small steps count','Look how far you’ve come.')+`<div class="soft split"><span>Milestones</span><strong>${items.filter(i=>i[2]).length} of ${items.length}</strong></div>`+items.map(([name,sub,done,route])=>L.row(name,sub,done?'check':'clock',`L.go('${route}')`,done?'<span class="pill">Done</span>':'')).join('');};
L.views.notifications=()=>{const pending=L.state.txs.filter(t=>t.status==='pending').length,gap=L.balances().gap;return L.header('Your updates','The things worth knowing.')+(pending?L.row('Payment in progress','Follow the same reference','clock',"L.go('pending')"):'')+(gap?L.row('Make room for your budget',m(gap)+' still to cover','plan',"L.go('makeRoom')"):'')+(!pending&&!gap?'<div class="empty"><h2>You’re all caught up.</h2><p class="small muted">Useful account and payment updates will appear here.</p></div>':'')+L.row('Your notification preferences','Choose the updates you want','bell',"L.go('notificationPrefs')");};
const tasks=[['Start from scratch','Create an account using the sample phone, code and identity. Reach Home.','welcome'],['Put money in','Try MoMo funding and external bank/GIP details. Check when the balance changes.','addMoney'],['Make a small plan','Add budget costs, then create and fund a separate Money Box.','plan'],['Pay someone','Send to Abena or pay a campus merchant. Review before confirming.','pay'],['Try a Pause Moment','Try low balance, repeat transfers and the scoring examples.','pauseDemo'],['Leave a payment pending','Choose the pending test result at authorisation. Reopen its reference and resolve it.','pending'],['Ask your money','Ask what you can spend and check the numbers against your plan.','chat'],['Try the merchant side','Use the sample business, create a sale and inspect its settlement.','merchant']];
L.views.testing=()=>L.header('Take Lumo for a spin.','Try it naturally. Notice what feels clear, awkward or missing.')+`<div class="notice"><strong>This is a testing prototype.</strong><p>Payments, identity checks, account numbers and messages are simulated. Don’t enter your real Ghana Card details, banking PIN or payment information. Each browser has its own local demo account.</p></div><div class="grid2">${L.btn('Start sign-up',L.state.onboarded?"L.go('resetConfirm')":"L.go('welcome')",'secondary')}${L.btn('Sample account',"L.go('sampleConfirm')",'secondary')}</div><p class="small muted" style="margin:15px 0">Sample account PIN and text code: <strong>123456</strong>. A PIN you choose during sign-up becomes that demo account’s PIN.</p><div class="test-list">${tasks.map(([t,sub,r],i)=>`<div class="test-step"><div><strong>${t}</strong><p>${sub}</p>${i&&L.state.onboarded?L.btn('Try this ↗',`L.go('${r}')`,'text-btn'):''}</div></div>`).join('')}</div><div class="actions">${L.btn('Leave feedback',"L.go('feedback')")}${L.btn('Pause response log',"L.go('pauseLog')",'secondary')}${L.btn('Export test session','L.exportSession()','secondary')}${L.btn('Reset this demo',"L.go('resetConfirm')",'text-btn')}</div><div class="notice"><strong>On your phone</strong><p>Open the link in Safari or Chrome. Use your browser’s “Add to Home Screen” option for an app-like launch. Test progress stays on this browser. Feedback is downloaded, so share that file with the Lumo team.</p></div>`;
L.views.sampleConfirm=()=>L.header('Try a lived-in Lumo account.','Start with GH₵720.00 operational + GH₵200.00 savings, a few payments and a sample plan.')+`<div class="notice">This replaces the demo account in this browser. Download your feedback first if you want to keep it.</div><div class="actions">${L.btn('Load sample account','L.explore()')}${L.btn('Keep my current demo','L.back()','secondary')}</div>`;
L.views.resetConfirm=()=>L.header('A fresh start?','Reset the demo on this browser and begin sign-up again.')+`<div class="notice">Your sample payments, plans and local feedback will be removed. You can export your test session first.</div><div class="actions">${L.btn('Export first','L.exportSession()','secondary')}${L.btn('Reset and start again','L.reset()','danger')}${L.btn('Keep my progress','L.back()','text-btn')}</div>`;
L.views.feedback=()=>L.header('Tell us how it felt.','Honest is useful. Specific is even better.')+`<span class="pill">SAVED ON THIS DEVICE</span><div class="form">${L.field('Your name or alias (optional)','feedbackName','For example, Kofi')}<label class="field"><span>How easy was Lumo to use?</span><select id="feedbackEase"><option value="">Choose a score</option><option value="5">5 · Very easy</option><option value="4">4 · Easy</option><option value="3">3 · Mixed</option><option value="2">2 · Difficult</option><option value="1">1 · Very difficult</option></select></label>${L.field('Which screen or task?','feedbackTask','For example, adding money')}<label class="field"><span>What happened? What would you change?</span><textarea id="feedbackText" placeholder="I expected… but…" maxlength="4000"></textarea></label><div id="error"></div><div class="actions">${L.btn('Save my feedback','L.saveFeedback()')}${L.btn('Download feedback to share','L.exportFeedback()','secondary')}</div></div><p class="small muted" style="margin-top:20px">Feedback isn’t sent automatically. Download it and share the file with the person who invited you.</p>${L.state.feedback.length?`<div class="section-head"><h2>${L.state.feedback.length} saved notes</h2></div>`+L.state.feedback.slice(-3).map(f=>`<div class="card" style="margin-top:10px"><strong>${esc(f.task||'Lumo experience')}</strong><p class="small muted" style="margin-top:6px">${esc(f.text)}</p></div>`).join(''):''}`;
L.saveFeedback=()=>{const text=L.value('feedbackText'),ease=L.value('feedbackEase');if(!text||!ease)return L.error('Choose a score and tell us a little about your experience.');L.clearFormDraft();L.state.feedback.push({id:L.id('feedback'),date:new Date().toISOString(),name:L.value('feedbackName'),ease:Number(ease),task:L.value('feedbackTask'),text});L.save();L.render();L.toast('Feedback saved. Download it to share with the team.');};
L.exportFeedback=()=>{if(!L.state.feedback.length)return L.toast('Save a feedback note first.');L.download('Lumo_Ambassador_Feedback.json',JSON.stringify({prototype:'Lumo Ambassador Preview 25',feedback:L.state.feedback},null,2),'application/json');};
L.exportSession=()=>{const s=L.state;L.download('Lumo_Test_Session.json',JSON.stringify({prototype:'Lumo Ambassador Preview 25',created:new Date().toISOString(),balances:L.balances(),payments:s.txs,plan:{allowance:s.allowance,essentials:s.essentials,goals:s.goals},feedback:s.feedback,pauseResponses:s.pauseEvents||[]},null,2),'application/json');};
// These forms use a single submit action, including the phone keyboard's Done key.
for(const [route,action] of Object.entries({allowance:'L.saveAllowance()',essentialEdit:'L.saveEssential()',goalEdit:'L.saveGoal()',allocate:'L.reviewAllocation()',releaseGoal:'L.reviewRelease()',storyTx:`L.setCategory(L.params.id)`,feedback:'L.saveFeedback()'})){
 const original=L.views[route];L.views[route]=()=>{const html=original();return `<form class="root-form" onsubmit="event.preventDefault();${action}">${html.replace(/<button type="button" class="primary" onclick="[^"]*">/,'<button type="submit" class="primary">')}</form>`;};
}
const deepRequest=new URLSearchParams(location.hash.slice(1)).get('request');L.route=L.state.closed?'accountInfo':L.state.onboarded?(L.state.locked?'signin':'home'):'welcome';L.params={};if(deepRequest){L.route='requestDetail';L.params={id:deepRequest};}
window.addEventListener('offline',()=>L.toast('You’re offline. This demo runs locally; no real service is connected.'));
})();
